/** Open task counts grouped by the canonical tenant/principal identity. */
export const openByAssignee = (tasks: readonly Task[]) => {
  const counts = new Map<string, { open: number; ownerPrincipalRef: NonNullable<Task['ownerPrincipalRef']> }>();
  for (const task of tasks) {
    if (task.ownerPrincipalRef !== undefined && taskStatusGroup(task.state) !== 'DONE') {
      const key = `${task.ownerPrincipalRef.tenantId}:${task.ownerPrincipalRef.principalId}`;
      const previous = counts.get(key);
      counts.set(key, { open: (previous?.open ?? 0) + 1, ownerPrincipalRef: task.ownerPrincipalRef });
    }
  }
  return [...counts.values()];
};

