/** Older entries written before the snapshot existed get the current Core display name at read time. */
const withActorNames = (
  tasks: readonly Task[],
  projects: readonly WorkProject[],
  names: ReadonlyMap<string, string>,
) => {
  if (names.size === 0) {
    return { projects, tasks };
  }
  const named = (history: readonly HistoryEntry[] | undefined) =>
    history?.map((entry) => {
      const name = entry.actorDisplayName ?? names.get(entry.actorPrincipalRef.principalId);
      return name === undefined ? entry : { ...entry, actorDisplayName: name };
    });
  return {
    projects: projects.map((project) =>
      project.history === undefined ? project : { ...project, history: named(project.history) ?? [] },
    ),
    tasks: tasks.map((task): Task => {
      const comments = task.comments?.map((comment) => {
        const name = comment.authorDisplayName ?? names.get(comment.authorPrincipalRef.principalId);
        return name === undefined ? comment : { ...comment, authorDisplayName: name };
      });
      return {
        ...task,
        ...(task.history === undefined ? {} : { history: named(task.history) ?? [] }),
        ...(comments === undefined ? {} : { comments }),
      };
    }),
  };
};

/** The stored Work row and the Core display names it mentions, as the owner transaction read them. */
export interface LoadedWorkRecords {
  readonly assignmentDirectory: AssignablePrincipalDirectory;
  readonly names: ReadonlyMap<string, string>;
  readonly revision: number;
  readonly state?: unknown;
}

/**
 * After commit: decodes the stored state, keeps the tasks the person may see (SpiceDB row filter when the
 * company grant is missing), and shapes the records response.
 */
export const finishWorkRecords = Effect.fn('Work.finishRecords')(function* finishWorkRecords(
  request: RecordsRequest,
  loaded: LoadedWorkRecords,
  grants: WorkRecordsGrants,
  scope: OperationalScope,
) {
  const { legalEntityId } = scope;
  if (legalEntityId === undefined) {
    return yield* referenceUnavailable();
  }
  const state =
    loaded.state === undefined
      ? yield* emptyWorkState(scope, legalEntityId).pipe(Effect.mapError(unavailable))
      : yield* Schema.decodeUnknownEffect(WorkStateSchema)(loaded.state).pipe(Effect.mapError(unavailable));
  const visible = yield* visibleWorkTasks(state.tasks, scope, grants.readAll);
  if (request.resourceId !== undefined && !visible.some((task) => task.ref.resourceId === request.resourceId)) {
    return yield* new WorkPermissionDenied({
      code: 'work_permission_denied',
      reason: 'Task detail is forbidden or absent',
    });
  }
  const items = visible.filter(
    (task) =>
      (request.resourceId === undefined || task.ref.resourceId === request.resourceId) &&
      // Hidden tasks stay out of lists; a direct link (one resourceId) still opens them.
      (task.archivedAt === undefined || request.resourceId !== undefined || request.includeArchived === true) &&
      (request.state === undefined || task.state === request.state) &&
      (request.ownerPrincipalId === undefined || task.ownerPrincipalRef?.principalId === request.ownerPrincipalId) &&
      (request.partyId === undefined || task.partyId === request.partyId) &&
      (request.opportunityId === undefined || task.opportunityId === request.opportunityId) &&
      (request.contextResourceId === undefined ||
        task.contextRefs.some((ref) => ref.resourceId === request.contextResourceId)),
  );
  const assignablePrincipals = yield* readAssignablePrincipals(loaded.assignmentDirectory, {
    moduleId: workModuleId,
    permission: 'module.access',
  }).pipe(Effect.mapError(referenceUnavailable));
  const departedPrincipalIds = new Set(
    loaded.assignmentDirectory.members.flatMap((member) =>
      member.membershipStatus === 'departed' ? [member.principalRef.principalId] : [],
    ),
  );
  const historicalTasks = items.map((task): Task => {
    if (taskStatusGroup(task.state) === 'DONE') {
      return Struct.omit(task, ['assignmentNeedsReassignment']);
    }
    return task.ownerPrincipalRef?.tenantId === scope.tenantId &&
      departedPrincipalIds.has(task.ownerPrincipalRef.principalId)
      ? { ...task, assignmentNeedsReassignment: true }
      : task;
  });
  const historicalProjects = (grants.readAll ? (state.projects ?? []) : []).map((project): WorkProject => {
    if (project.state === 'DONE') {
      return Struct.omit(project, ['assignmentNeedsReassignment']);
    }
    return project.responsiblePrincipalRef?.tenantId === scope.tenantId &&
      departedPrincipalIds.has(project.responsiblePrincipalRef.principalId)
      ? { ...project, assignmentNeedsReassignment: true }
      : project;
  });
  const named = withActorNames(historicalTasks, historicalProjects, loaded.names);
  const visiblePrincipalIds = new Set([
    scope.principalId,
    ...assignablePrincipals.map(({ principalRef }) => principalRef.principalId),
    ...historicalTasks.flatMap((task) => [
      ...(task.ownerPrincipalRef === undefined ? [] : [task.ownerPrincipalRef.principalId]),
      ...(task.comments ?? []).map(({ authorPrincipalRef }) => authorPrincipalRef.principalId),
      ...(task.history ?? []).map(({ actorPrincipalRef }) => actorPrincipalRef.principalId),
    ]),
    ...historicalProjects.flatMap((project) => [
      ...(project.responsiblePrincipalRef === undefined ? [] : [project.responsiblePrincipalRef.principalId]),
      ...(project.history ?? []).map(({ actorPrincipalRef }) => actorPrincipalRef.principalId),
    ]),
  ]);
  const referenceDate = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Prague' }).format(
    DateTime.toDateUtc(yield* DateTime.now),
  );
  return {
    actorPrincipalRef: { principalId: scope.principalId, tenantId: scope.tenantId },
    assignablePrincipals,
    principalNames: [...loaded.names].flatMap(([principalId, displayName]) =>
      visiblePrincipalIds.has(principalId)
        ? [{ displayName, principalRef: { principalId, tenantId: scope.tenantId } }]
        : [],
    ),
    canWrite: grants.writeAll && isConnectionWriteAllowed(scope, workModuleId),
    collection: state.collection,
    indicators: {
      open: items.filter((task) => taskStatusGroup(task.state) !== 'DONE').length,
      openByAssignee: openByAssignee(items),
      overdue: items.filter((task) => taskIsOverdue(task, referenceDate)).length,
    },
    items: named.tasks,
    lookupAccess: grants.lookupAccess,
    projects: named.projects,
    referenceDate,
    revision: loaded.revision,
  };
});

const validWriteDecision = (
  decisions: Effect.Success<ReturnType<ContextAccessService['resources']>>,
  ref: Task['ref'],
) =>
  decisions.length === 1 &&
  decisions[0]?.key === `${ref.moduleId}:${ref.resourceType}:${ref.resourceId}` &&
  decisions[0]?.decision !== 'unavailable';

export const persistenceService = Effect.fn('Work.persistenceService')(
  function* makePersistence(transaction: ScopedTransactionExecutor, scope: OperationalScope) {
    const { legalEntityId } = scope;
    if (
      legalEntityId === undefined ||
      transaction.scope.tenantId !== scope.tenantId ||
      transaction.scope.legalEntityId !== legalEntityId
    ) {
      return yield* new WorkScopeMismatch({
        code: 'work_scope_mismatch',
        reason: 'A scoped company transaction is required',
      });
    }
    const access = yield* ContextAccess;
    const injectedVerifier = yield* Effect.serviceOption(WorkReferenceVerifier);
    const source = yield* makeReferenceGatewayCredentialSource(scope).pipe(Effect.mapError(referenceUnavailable));
    const verifier = Option.getOrElse(injectedVerifier, () => makeWorkReferenceVerifier(source));
    const actor = { principalId: scope.principalId, tenantId: scope.tenantId };
    // The Action policy checks target permissions before Core opens the transaction. Recheck
    // mutable lifecycle/company membership here, in the same snapshot that commits the owner state.
    const resolveAssignee = Effect.fn('Work.revalidateAssignee')(function* revalidateAssignee(principal: PrincipalRef) {
      const directory = yield* loadAssignablePrincipalDirectory(transaction, scope).pipe(
        Effect.mapError(referenceUnavailable),
      );
      return yield* activeAssignmentMember(directory, principal).pipe(
        Effect.mapError((cause) =>
          Object.defineProperty(
            new WorkReferenceIneligible({
              code: 'work_reference_ineligible',
              reason: 'Assignment target is ineligible',
            }),
            'cause',
            { enumerable: false, value: cause },
          ),
        ),
      );
    });
    /**
     * Core display names of the given principals in this tenant. Best-effort: an unreadable principal table leaves
     * the names out and history falls back to a generic label instead of failing the command or the read.
     */
    const principalNames = Effect.fn('Work.principalNames')(function* principalNames(ids: ReadonlySet<string>) {
      if (ids.size === 0) {
        return new Map<string, string>();
      }
      const rows = yield* transaction
        .select({ displayName: corePrincipals.displayName, principalId: corePrincipals.principalId })
        .from(corePrincipals)
        .where(and(eq(corePrincipals.tenantId, scope.tenantId), inArray(corePrincipals.principalId, [...ids])))
        .pipe(Effect.catchCause(() => Effect.succeed([])));
      return new Map(rows.map((row) => [row.principalId, row.displayName] as const));
    });
    /** The acting account's Core display name, snapshotted into every history entry and comment it writes. */
    const actorDisplayName = Effect.fn('Work.actorDisplayName')(function* actorDisplayName() {
      return (yield* principalNames(new Set([scope.principalId]))).get(scope.principalId);
    });
    const whereScope = and(eq(workStates.tenantId, scope.tenantId), eq(workStates.legalEntityId, legalEntityId));
    const load = Effect.fn('Work.load')(function* load() {
      const [row] = yield* transaction.select().from(workStates).where(whereScope).limit(1);
      if (row === undefined) {
        return { revision: 0, state: yield* emptyWorkState(scope, legalEntityId) };
      }
      const state = yield* Schema.decodeUnknownEffect(WorkStateSchema)(row.state);
      return { revision: row.revision, state };
    }, Effect.mapError(unavailable));
    /**
     * The records read's whole transaction step: the raw state row and the display names of every principal it
     * mentions. Decoding and visibility filtering run after commit in {@link finishWorkRecords}.
     */
    const loadRecords = Effect.fn('Work.loadRecords')(function* loadRecords() {
      const assignmentDirectory = yield* loadAssignablePrincipalDirectory(transaction, scope);
      const [row] = yield* transaction
        .select({ revision: workStates.revision, state: workStates.state })
        .from(workStates)
        .where(whereScope)
        .limit(1);
      if (row === undefined) {
        return {
          assignmentDirectory,
          names: new Map(
            assignmentDirectory.members.map(({ displayName, principalRef }) => [principalRef.principalId, displayName]),
          ),
          revision: 0,
        } satisfies LoadedWorkRecords;
      }
      const mentioned = yield* transaction
        .select({ displayName: corePrincipals.displayName, principalId: corePrincipals.principalId })
        .from(corePrincipals)
        .where(
          and(
            eq(corePrincipals.tenantId, scope.tenantId),
            sql`${corePrincipals.principalId}::text in (select jsonb_path_query(${workStates.state}, 'lax $.**.principalId') #>> '{}' from ${workStates} where ${whereScope})`,
          ),
        )
        // Best-effort: an unreadable principal table leaves the names out and history shows a generic label.
        .pipe(Effect.catchCause(() => Effect.succeed([])));
      return {
        assignmentDirectory,
        names: new Map([
          ...mentioned.map((entry) => [entry.principalId, entry.displayName] as const),
          ...assignmentDirectory.members.map(
            ({ displayName, principalRef }) => [principalRef.principalId, displayName] as const,
          ),
        ]),
        revision: row.revision,
        state: row.state,
      } satisfies LoadedWorkRecords;
    }, Effect.mapError(unavailable));
    const save = Effect.fn('Work.save')(function* save(expectedRevision: number, state: WorkState) {
      const encoded = yield* Schema.encodeEffect(WorkStateSchema)(state).pipe(Effect.mapError(unavailable));
      const updatedAt = yield* DateTime.now;
      if (expectedRevision === 0) {
        const inserted = yield* transaction
          .insert(workStates)
          .values({
            legalEntityId,
            revision: 1,
            state: encoded,
            tenantId: scope.tenantId,
            updatedAt: DateTime.toDateUtc(updatedAt),
          })
          .onConflictDoNothing()
          .returning({ revision: workStates.revision })
          .pipe(Effect.mapError(unavailable));
        if (inserted.length === 1) {
          return 1;
        }
      }
      const rows = yield* transaction
        .update(workStates)
        .set({ revision: expectedRevision + 1, state: encoded, updatedAt: DateTime.toDateUtc(updatedAt) })
        .where(and(whereScope, eq(workStates.revision, expectedRevision)))
        .returning({ revision: workStates.revision })
        .pipe(Effect.mapError(unavailable));
      if (rows.length !== 1) {
        return yield* new WorkRevisionConflict({
          code: 'work_revision_conflict',
          reason: workChangedReason,
        });
      }
      return expectedRevision + 1;
    });
    const applyBulk = Effect.fn('Work.applyBulk')(function* applyBulk(
      command: BulkWorkCommand,
      expectedRevision: number,
    ) {
      const targets: readonly TaskRef[] = yield* Effect.forEach(
        command.ids,
        (resourceId) =>
          Schema.decodeEffect(TaskRefSchema)({
            moduleId: workModuleId,
            resourceId,
            resourceType: 'work.tasks.task',
            tenantId: scope.tenantId,
          }).pipe(Effect.mapError(invalidTaskIdentity)),
        { concurrency: 1 },
      );
      if (!(yield* contextGrant(scope, 'write_all'))) {
        const decisions = yield* access.resources({
          legalEntityId,
          permission: 'write',
          principalId: scope.principalId,
          resources: targets,
          tenantId: scope.tenantId,
        });
        if (
          decisions.length !== targets.length ||
          decisions.some(
            (decision, index) =>
              decision.decision === 'unavailable' ||
              decision.key !==
                `${targets[index]?.moduleId}:${targets[index]?.resourceType}:${targets[index]?.resourceId}`,
          )
        ) {
          return yield* referenceUnavailable();
        }
        // Fail closed: one forbidden id rejects the whole batch so nothing changes silently.
        if (decisions.some((decision) => decision.decision !== 'allowed')) {
          return yield* new WorkPermissionDenied({
            code: 'work_permission_denied',
            reason: 'Task mutation is forbidden',
          });
        }
      }
      const snapshot = yield* load();
      if (snapshot.revision !== expectedRevision) {
        return yield* new WorkRevisionConflict({
          code: 'work_revision_conflict',
          reason: workChangedReason,
        });
      }
      const now = yield* DateTime.now;
      const change = yield* evolveBulkWorkState(snapshot.state, command, { now, tenantId: scope.tenantId });
      if (!change.changed) {
        return { results: change.results, revision: expectedRevision };
      }
      if (Predicate.isTagged('BulkAssignTasks')(command) && Option.isSome(command.ownerPrincipalRef)) {
        yield* resolveAssignee(command.ownerPrincipalRef.value);
      }
      const revision = yield* save(
        expectedRevision,
        withHistory(snapshot.state, change.state, actor, now, yield* actorDisplayName()),
      );
      return { results: change.results, revision };
    });
    const apply = Effect.fn('Work.apply')(function* apply(
      command: WorkCommand,
      expectedRevision: number,
      resourceId: string,
    ) {
      if (Schema.is(BulkWorkCommandSchema)(command)) {
        return yield* applyBulk(command, expectedRevision);
      }
      if (Schema.is(PlanningCommandSchema)(command)) {
        if (!(yield* contextGrant(scope, 'write_all'))) {
          return yield* new WorkPermissionDenied({
            code: 'work_permission_denied',
            reason: 'Planning changes require Work write permission',
          });
        }
        const snapshot = yield* load();
        if (snapshot.revision !== expectedRevision) {
          return yield* new WorkRevisionConflict({ code: 'work_revision_conflict', reason: workChangedReason });
        }
        const now = yield* DateTime.now;
        if (Predicate.isTagged('AddTaskComment')(command)) {
          const task = snapshot.state.tasks.find((item) => item.ref.resourceId === command.taskRef.resourceId);
          if (task === undefined || command.taskRef.tenantId !== scope.tenantId) {
            return yield* new WorkNotFound({
              code: 'work_not_found',
              reason: 'Task does not exist in the authorized company',
            });
          }
          const authorDisplayName = yield* actorDisplayName();
          const updated = {
            ...task,
            comments: [
              ...(task.comments ?? []),
              {
                id: resourceId,
                ...(authorDisplayName === undefined ? {} : { authorDisplayName }),
                authorPrincipalRef: { principalId: scope.principalId, tenantId: scope.tenantId },
                createdAt: now,
                text: command.text,
              },
            ],
            updatedAt: now,
          };
          const revision = yield* save(expectedRevision, {
            ...snapshot.state,
            tasks: snapshot.state.tasks.map((item) => (item.ref.resourceId === task.ref.resourceId ? updated : item)),
          });
          return { revision, task: updated };
        }
        if (command.responsiblePrincipalRef.tenantId !== scope.tenantId) {
          return yield* new WorkScopeMismatch({
            code: 'work_scope_mismatch',
            reason: 'Project responsibility must belong to the trusted tenant',
          });
        }
        if (
          command.plannedStart > command.plannedEnd ||
          command.milestones.some((item) => item.dueDate < command.plannedStart || item.dueDate > command.plannedEnd)
        ) {
          return yield* new WorkLifecycleConflict({
            code: 'work_lifecycle_conflict',
            reason: 'Project dates or milestone dates are outside the planned period',
          });
        }
        const projects = snapshot.state.projects ?? [];
        const existing = Predicate.isTagged('UpdateProject')(command)
          ? projects.find((item) => item.id === command.id)
          : undefined;
        if (Predicate.isTagged('UpdateProject')(command) && existing === undefined) {
          return yield* new WorkNotFound({
            code: 'work_not_found',
            reason: 'Project does not exist in the authorized company',
          });
        }
        const responsibilityChanged =
          existing?.responsiblePrincipalRef?.tenantId !== command.responsiblePrincipalRef.tenantId ||
          existing.responsiblePrincipalRef.principalId !== command.responsiblePrincipalRef.principalId;
        if (responsibilityChanged) {
          yield* resolveAssignee(command.responsiblePrincipalRef);
        }
        const project: WorkProject = {
          ...(responsibilityChanged ? undefined : existing),
          createdAt: existing?.createdAt ?? now,
          id: Predicate.isTagged('UpdateProject')(command) ? command.id : resourceId,
          milestones: command.milestones,
          plannedEnd: command.plannedEnd,
          plannedStart: command.plannedStart,
          responsiblePrincipalRef: command.responsiblePrincipalRef,
          state: command.state,
          title: command.title,
          updatedAt: now,
        };
        const recorded = withHistory(
          snapshot.state,
          { ...snapshot.state, projects: [...projects.filter((item) => item.id !== project.id), project] },
          actor,
          now,
          yield* actorDisplayName(),
        );
        const revision = yield* save(expectedRevision, recorded);
        return { project: recorded.projects?.find((item) => item.id === project.id) ?? project, revision };
      }
      if (!(yield* contextGrant(scope, 'write_all'))) {
        if (Predicate.isTagged('CreateTask')(command)) {
          return yield* new WorkPermissionDenied({
            code: 'work_permission_denied',
            reason: 'Creating Tasks requires Work write permission',
          });
        }
        const decisions = yield* access.resources({
          legalEntityId,
          permission: 'write',
          principalId: scope.principalId,
          resources: [command.taskRef],
          tenantId: scope.tenantId,
        });
        if (!validWriteDecision(decisions, command.taskRef)) {
          return yield* referenceUnavailable();
        }
        if (decisions[0]?.decision !== 'allowed') {
          return yield* new WorkPermissionDenied({
            code: 'work_permission_denied',
            reason: 'Task mutation is forbidden',
          });
        }
      }
      const snapshot = yield* load();
      if (Predicate.isTagged('CreateTask')(command) && command.storefrontInquiry !== undefined) {
        const inquiry = command.storefrontInquiry;
        const existing = snapshot.state.tasks.find((task) => task.storefrontInquiry?.requestId === inquiry.requestId);
        if (existing !== undefined) {
          if (
            !(['requestId', 'kind', 'name', 'email', 'subject', 'message', 'productId'] as const).every(
              (key) => existing.storefrontInquiry?.[key] === inquiry[key],
            )
          ) {
            return yield* new WorkLifecycleConflict({
              code: 'work_lifecycle_conflict',
              reason: 'Inquiry request id already belongs to another submission',
            });
          }
          return { revision: snapshot.revision, task: existing };
        }
      }
      if (snapshot.revision !== expectedRevision) {
        return yield* new WorkRevisionConflict({
          code: 'work_revision_conflict',
          reason: workChangedReason,
        });
      }
      const selectedProjectId = Match.value(command).pipe(
        Match.tag('CreateTask', ({ projectId }) => Option.fromUndefinedOr(projectId)),
        Match.tag('UpdateTask', ({ projectId }) => projectId ?? Option.none()),
        Match.tag('AssignTask', 'ChangeTaskState', 'SetTaskArchived', () => Option.none()),
        Match.exhaustive,
        Option.getOrUndefined,
      );
      if (
        selectedProjectId !== undefined &&
        !(snapshot.state.projects ?? []).some((project) => project.id === selectedProjectId)
      ) {
        return yield* new WorkReferenceIneligible({
          code: 'work_reference_ineligible',
          reason: 'Project must belong to the authorized company',
        });
      }
      const owner = changedAssignmentTarget(command, snapshot.state);
      if (owner !== undefined) {
        yield* resolveAssignee(owner);
      }
      if (
        (Predicate.isTagged('CreateTask')(command) || Predicate.isTagged('UpdateTask')(command)) &&
        (command.contextRefs?.length ?? 0) > 0
      ) {
        yield* verifier.verify(command.contextRefs ?? [], scope);
      }
      const now = yield* DateTime.now;
      const change = yield* evolveWorkState(snapshot.state, command, {
        now,
        resourceId,
        tenantId: scope.tenantId,
      });
      const recorded = withHistory(snapshot.state, change.state, actor, now, yield* actorDisplayName());
      const revision = yield* save(expectedRevision, recorded);
      return {
        revision,
        task: recorded.tasks.find((item) => item.ref.resourceId === change.task.ref.resourceId) ?? change.task,
      };
    });
    return { apply, loadRecords };
  },
  Effect.mapError((cause) =>
    Object.defineProperty(
      new OperationContextUnavailable({
        code: 'operation_context_unavailable',
        reason: 'Owner-scoped services are temporarily unavailable',
      }),
      'cause',
      { enumerable: false, value: cause },
    ),
  ),
);
